import * as esbuild from "esbuild";
import path from "path";
import fs from "fs";

async function build() {
  console.log("🔨 Building production client SPA bundle (app-v3.js)...");
  await esbuild.build({
    entryPoints: ["src/entry-client.tsx"],
    bundle: true,
    minify: true,
    format: "esm",
    target: ["es2022"],
    outfile: "dist/client/assets/app-v3.js",
    define: {
      "process.env.NODE_ENV": '"production"',
      "import.meta.env": JSON.stringify({
        PROD: true,
        DEV: false,
        MODE: "production",
        VITE_SITE_URL: "https://anamonofficial.com",
        VITE_API_URL: "",
        VITE_SUPABASE_URL: "https://c--05c6c740-ba8c-4a01-bcbf-ad016f412410-prod.lovable.cloud",
        VITE_SUPABASE_PUBLISHABLE_KEY: "sb_publishable__AFZcnPcx6PjXpFNiNlV0g_ciSSWNhy",
        VITE_SUPABASE_PROJECT_ID: "ydkdicudwhxrukppucxy",
      }),
      "import.meta.env.PROD": "true",
      "import.meta.env.DEV": "false",
      "import.meta.env.MODE": '"production"',
      "import.meta.env.VITE_API_URL": '""',
      "import.meta.env.VITE_SITE_URL": '"https://anamonofficial.com"',
      "import.meta.env.VITE_SUPABASE_URL": '"https://c--05c6c740-ba8c-4a01-bcbf-ad016f412410-prod.lovable.cloud"',
      "import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY": '"sb_publishable__AFZcnPcx6PjXpFNiNlV0g_ciSSWNhy"',
      "import.meta.env.VITE_SUPABASE_PROJECT_ID": '"ydkdicudwhxrukppucxy"',
    },
    loader: {
      ".jpg": "file",
      ".png": "file",
      ".svg": "file",
      ".css": "empty",
    },
    alias: {
      "@": path.resolve("./src"),
    },
  });
  console.log("✅ Successfully built dist/client/assets/app-v3.js !");

  // Find the CSS asset generated by Vite
  const assetsDir = path.resolve("./dist/client/assets");
  let cssFile = "styles.css";
  if (fs.existsSync(assetsDir)) {
    const files = fs.readdirSync(assetsDir);
    const matched = files.find((f) => f.startsWith("styles-") && f.endsWith(".css"));
    if (matched) cssFile = matched;
  }

  // Schema.org JSON-LD Structured Data
  const jsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": "https://anamonofficial.com/#organization",
        "name": "Anamon",
        "url": "https://anamonofficial.com",
        "logo": "https://anamonofficial.com/favicon.jpg",
        "description": "Pakistan's premier B2B wholesale footwear marketplace and direct manufacturing network.",
        "contactPoint": {
          "@type": "ContactPoint",
          "telephone": "+92-300-1234567",
          "contactType": "wholesale sales",
          "areaServed": "PK",
          "availableLanguage": ["English", "Urdu"]
        }
      },
      {
        "@type": "WebSite",
        "@id": "https://anamonofficial.com/#website",
        "url": "https://anamonofficial.com",
        "name": "Anamon Wholesale Footwear",
        "publisher": {
          "@id": "https://anamonofficial.com/#organization"
        }
      }
    ]
  };

  const htmlContent = `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=5.0" />
    <title>Anamon — Pakistan's Wholesale Footwear Marketplace</title>
    <meta
      name="description"
      content="Anamon is Pakistan's premier B2B wholesale footwear marketplace. Direct factory sourcing for retailers, distributors & online sellers across Pakistan. Men, women & kids bulk orders."
    />
    <meta property="og:title" content="Anamon — Wholesale Footwear Marketplace" />
    <meta
      property="og:description"
      content="B2B footwear manufacturing for retailers, distributors & online sellers across Pakistan."
    />
    <meta property="og:type" content="website" />
    <meta property="og:url" content="https://anamonofficial.com" />
    <meta property="og:site_name" content="Anamon Wholesale" />
    <meta name="twitter:card" content="summary_large_image" />
    <link rel="icon" type="image/jpeg" href="/favicon.jpg" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap"
      rel="stylesheet"
    />
    <link rel="preload" href="/assets/${cssFile}" as="style" />
    <link rel="stylesheet" href="/assets/${cssFile}" />
    <link rel="modulepreload" href="/assets/app-v3.js" />
    <script type="application/ld+json">
${JSON.stringify(jsonLd, null, 2)}
    </script>
  </head>
  <body>
    <div id="root"></div>
    <script type="module" src="/assets/app-v3.js"></script>
  </body>
</html>`;

  fs.writeFileSync(path.resolve("./dist/client/index.html"), htmlContent, "utf-8");
  fs.writeFileSync(path.resolve("./public/index.html"), htmlContent, "utf-8");
  
  // Copy production .htaccess to dist/client
  if (fs.existsSync(path.resolve("./public/.htaccess"))) {
    fs.copyFileSync(path.resolve("./public/.htaccess"), path.resolve("./dist/client/.htaccess"));
  }

  console.log(`✅ Production assets injected & .htaccess synced !`);
}

build().catch((err) => {
  console.error("Bundle error:", err);
  process.exit(1);
});
